#!/usr/bin/env python3
"""Plot sanitized B1.10 comparisons generated by the Tier-B controller."""

from __future__ import annotations

import argparse
import html
import json
import math
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]


def load_comparisons(root: Path):
    records = []
    for path in sorted(root.rglob("comparison.json")):
        value = json.loads(path.read_text(encoding="utf-8"))
        if value.get("schema_version") == "b1.10-v1":
            records.append(value)
    if not records:
        raise SystemExit(f"No B1.10 comparison.json files found under {root}")
    return records


def number(value):
    try:
        return float(value)
    except (TypeError, ValueError):
        return math.nan


def paired(records, getter):
    return (
        [getter(item["executions"]["k8s"]) for item in records],
        [getter(item["executions"]["mn5"]) for item in records],
    )


def grouped_plot(output, labels, title, ylabel, k8s_values, hpc_values):
    width = max(800, len(labels) * 240)
    height = 480
    left, top, bottom = 80, 60, 110
    plot_width = width - left - 30
    plot_height = height - top - bottom
    finite = [
        value
        for value in k8s_values + hpc_values
        if isinstance(value, (int, float)) and math.isfinite(value)
    ]
    maximum = max(finite, default=1.0) or 1.0
    group_width = plot_width / max(len(labels), 1)
    bar_width = min(54, group_width * 0.3)
    lines = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
        '<rect width="100%" height="100%" fill="white"/>',
        f'<text x="{width / 2}" y="30" text-anchor="middle" font-size="20">{html.escape(title)}</text>',
        f'<text x="20" y="{top + plot_height / 2}" text-anchor="middle" font-size="13" transform="rotate(-90 20 {top + plot_height / 2})">{html.escape(ylabel)}</text>',
        f'<line x1="{left}" y1="{top}" x2="{left}" y2="{top + plot_height}" stroke="black"/>',
        f'<line x1="{left}" y1="{top + plot_height}" x2="{left + plot_width}" y2="{top + plot_height}" stroke="black"/>',
    ]
    for index, label in enumerate(labels):
        center = left + group_width * (index + 0.5)
        for offset, value, color in (
            (-bar_width, k8s_values[index], "#4c78a8"),
            (0, hpc_values[index], "#f58518"),
        ):
            x = center + offset
            if isinstance(value, (int, float)) and math.isfinite(value):
                bar_height = max(0.0, value) / maximum * plot_height
                y = top + plot_height - bar_height
                lines.append(
                    f'<rect x="{x:.1f}" y="{y:.1f}" width="{bar_width:.1f}" height="{bar_height:.1f}" fill="{color}"/>'
                )
                lines.append(
                    f'<text x="{x + bar_width / 2:.1f}" y="{max(y - 5, top + 12):.1f}" text-anchor="middle" font-size="10">{value:.4g}</text>'
                )
            else:
                lines.append(
                    f'<text x="{x + bar_width / 2:.1f}" y="{top + plot_height - 5}" text-anchor="middle" font-size="10">N/A</text>'
                )
        lines.append(
            f'<text x="{center:.1f}" y="{top + plot_height + 25}" text-anchor="middle" font-size="11">{html.escape(label)}</text>'
        )
    legend_y = height - 25
    lines.extend([
        f'<rect x="{left}" y="{legend_y - 12}" width="14" height="14" fill="#4c78a8"/>',
        f'<text x="{left + 20}" y="{legend_y}" font-size="12">Kubernetes</text>',
        f'<rect x="{left + 120}" y="{legend_y - 12}" width="14" height="14" fill="#f58518"/>',
        f'<text x="{left + 140}" y="{legend_y}" font-size="12">HPC/Slurm</text>',
        '</svg>',
    ])
    output.write_text("\n".join(lines) + "\n", encoding="utf-8")


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument(
        "--evidence",
        type=Path,
        default=ROOT / "artifacts" / "benchmarks",
        help="Directory containing generated B1.10 comparison.json files",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=ROOT / "artifacts" / "plots",
        help="Directory for generated plots",
    )
    args = parser.parse_args()
    records = load_comparisons(args.evidence)
    args.output.mkdir(parents=True, exist_ok=True)
    labels = [item["workload_profile"] for item in records]

    plots = (
        ("end_to_end_time.svg", "End-to-End Completion Time", "Seconds", lambda item: number(item.get("timing", {}).get("end_to_end_s"))),
        ("queue_wait.svg", "Scheduler / Queue Delay", "Seconds", lambda item: number(item.get("timing", {}).get("queue_wait_s"))),
        ("execution_runtime.svg", "Scheduler-Observed Execution Runtime", "Seconds", lambda item: number(item.get("timing", {}).get("execution_time_s"))),
        ("inference_throughput.svg", "Inference Throughput", "Samples / second", lambda item: number(item.get("workload", {}).get("throughput"))),
        ("peak_memory.svg", "Peak Workload Memory", "MB", lambda item: number(item.get("resources", {}).get("peak_memory_mb"))),
    )
    for filename, title, ylabel, getter in plots:
        k8s_values, hpc_values = paired(records, getter)
        grouped_plot(args.output / filename, labels, title, ylabel, k8s_values, hpc_values)

    print("B1.10_PLOTS=PASS")
    print(f"INPUT_DIR={args.evidence.resolve()}")
    print(f"OUTPUT_DIR={args.output.resolve()}")


if __name__ == "__main__":
    main()
